import{_ as n,a0 as l,w as p,s as i,ao as u,I as r,x as e,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"感謝開源和自由軟件維護者的 10 種方法 | LCTT x X-CMD","titleTemplate":false,"description":"感謝開源和自由軟件維護者的 10 種方法 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"感謝開源和自由軟件維護者的 10 種方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"感謝開源和自由軟件維護者的 10 種方法 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181121 10 ways to give thanks to open source and free software maintainers","title":"感謝開源和自由軟件維護者的 10 種方法","tag":"201812","desc":""},"relativePath":"201812/20181121 10 ways to give thanks to open source and free software maintainers.md","filePath":"[post].md"}'),d={name:"201812/20181121 10 ways to give thanks to open source and free software maintainers.md"};function f(m,t,g,T,k,x){const s=l("Link");return p(),i("div",null,[t[18]||(t[18]=u('<h1 id="感謝開源和自由軟件維護者的-10-種方法" tabindex="-1">感謝開源和自由軟件維護者的 10 種方法 <a class="header-anchor" href="#感謝開源和自由軟件維護者的-10-種方法" aria-label="Permalink to “感謝開源和自由軟件維護者的 10 種方法”">​</a></h1><blockquote><p>如何表達你的感激之情。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/world_hands_diversity.png?itok=zm4EDxgE" alt=""></p><p>每天，我使用的那些高質量的軟件 —— 開發和維護這些軟件的人不需要我為之付款，他們尊重我的自由，並且慷慨地付出時間和精力。</p><p>在這個感恩的季節，我鼓勵那些也使用和欣賞開源和自由軟件維護者工作的人表達你的感激之情。以下是十種方法：</p><h3 id="容易做到的" tabindex="-1">容易做到的 <a class="header-anchor" href="#容易做到的" aria-label="Permalink to “容易做到的”">​</a></h3><p>1、發送電子郵件感謝開發人員。具體點説，告訴他們你使用他們的什麼軟件以及它是如何幫助了你。</p><p>2、使用你最喜愛的社交媒體平台宣傳它。</p><p>3、寫一篇關於你最喜歡的軟件的Blog文章。</p><h3 id="捐款" tabindex="-1">捐款 <a class="header-anchor" href="#捐款" aria-label="Permalink to “捐款”">​</a></h3><p>4、如果你最喜歡的開源項目接受捐款，請匯款。</p><p>5、如果你受僱於使用開源軟件的公司，看你是否可以説服管理層贊助某些項目。</p><p>6、盡你所能地捐款。社交動機能做的不可思議！</p><h3 id="花費時間" tabindex="-1">花費時間 <a class="header-anchor" href="#花費時間" aria-label="Permalink to “花費時間”">​</a></h3><p>7、幫助審查補丁。</p><p>8、幫助分類 bug。</p>',16)),r("p",null,[t[1]||(t[1]=e("9、回答 IRC、郵件列表或 ",-1)),o(s,{href:"https://meta.stackoverflow.com/"},{default:a(()=>[...t[0]||(t[0]=[e("Stack Overflow",-1)])]),_:1}),t[2]||(t[2]=e(" 中的問題。",-1))]),t[19]||(t[19]=r("p",null,[r("strong",null,"10、額外的："),e("如果你像我一樣，你在某個時候對開源社區的其他人説了一些嚴厲的話。承諾做得更好：用善良和開放溝通。感謝的最好方式是讓開源社區成為人們能舒適溝通的地方。")],-1)),t[20]||(t[20]=r("hr",null,null,-1)),r("p",null,[t[4]||(t[4]=e("via: ",-1)),o(s,{href:"https://opensource.com/article/18/11/ways-give-thanks-open-source"},{default:a(()=>[...t[3]||(t[3]=[e("https://opensource.com/article/18/11/ways-give-thanks-open-source",-1)])]),_:1})]),r("p",null,[t[9]||(t[9]=e("作者：",-1)),o(s,{href:"https://opensource.com/users/moshez"},{default:a(()=>[...t[5]||(t[5]=[e("Moshe Zadka",-1)])]),_:1}),t[10]||(t[10]=e(" 選題：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[6]||(t[6]=[e("lujun9972",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:a(()=>[...t[7]||(t[7]=[e("geekpi",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[15]||(t[15]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const h=n(d,[["render",f]]);export{b as __pageData,h as default};
